import{_ as e,o as l,c as n,a2 as o}from"./chunks/framework.BBdhqAg0.js";const r="data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mNkYAAAAAYAAjCB0C8AAAAASUVORK5CYII=",y=JSON.parse('{"title":"유닛 정보 설정","description":"","frontmatter":{},"headers":[],"relativePath":"project/units.md","filePath":"project/units.md","lastUpdated":1793110964000}'),a={name:"project/units.md"};function d(s,t,g,i,c,h){return l(),n("div",null,[...t[0]||(t[0]=[o('<h1 id="유닛-정보-설정" tabindex="-1">유닛 정보 설정 <a class="header-anchor" href="#유닛-정보-설정" aria-label="Permalink to &quot;유닛 정보 설정&quot;">​</a></h1><div class="tip custom-block"><p class="custom-block-title">📸 실제 화면 안내</p><p><img src="'+r+'" alt="동호수 유닛 배치도 및 등록 화면"><em>관리자 참고: 해당 화면의 실제 캡처 이미지를 <code>./images/units.png</code> 경로에 등록해 주세요.</em></p></div><blockquote><p><strong>유닛 정보 설정</strong>은 프로젝트의 동(건물) 정보를 등록하고, 해당 동에 속한 각 호수(유닛)를 일괄 또는 개별적으로 생성하여 분양 공급 대상 세대 목록과 시각적 배치도를 구축하는 모듈입니다.</p></blockquote><ul><li><strong>접근 경로</strong>: 시스템 좌측 내비게이션 메뉴에서 **[PJT 관리 시스템] → [프로젝트 설정] → [유닛 정보 설정]**을 선택하여 접속합니다.</li></ul><h2 id="_1-동-건물-등록" tabindex="-1">1. 동(건물) 등록 <a class="header-anchor" href="#_1-동-건물-등록" aria-label="Permalink to &quot;1. 동(건물) 등록&quot;">​</a></h2><p>프로젝트를 구성하는 각 동(건물)의 명칭을 등록합니다. 유닛을 등록하기 위해 반드시 선행되어야 하는 단계입니다.</p><ul><li><strong>위치</strong>: <code>프로젝트 설정 &gt; 유닛 정보 설정 &gt; 동(건물) 등록</code></li></ul><table tabindex="0"><thead><tr><th style="text-align:left;">라벨</th><th style="text-align:center;">필수입력</th><th style="text-align:left;">상세 설명 및 실무 기준</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>동(건물) 이름</strong></td><td style="text-align:center;"><strong>필수</strong></td><td style="text-align:left;">해당 건물을 식별할 명칭 입력 (예: <code>101동</code>, <code>A동</code>, <code>상가동</code> 등)</td></tr></tbody></table><blockquote><p><strong>⚠️ 주의사항</strong>: 해당 동에 이미 등록된 유닛(호수) 데이터가 존재하는 경우, 데이터 무결성을 위해 하위 유닛을 모두 삭제한 후에만 동 정보를 삭제할 수 있습니다.</p></blockquote><h2 id="_2-호-유닛-등록" tabindex="-1">2. 호(유닛) 등록 <a class="header-anchor" href="#_2-호-유닛-등록" aria-label="Permalink to &quot;2. 호(유닛) 등록&quot;">​</a></h2><p>등록된 동(건물)별로 실제 분양/공급 대상인 호수(유닛) 정보를 생성합니다. 라인과 층 범위를 지정하여 일괄 등록하거나, 개별 유닛의 상태(홀딩 등)를 지정할 수 있습니다.</p><ul><li><strong>위치</strong>: <code>프로젝트 설정 &gt; 유닛 정보 설정 &gt; 호(유닛) 등록</code></li></ul><h3 id="_1-호수-유닛-일괄-등록" tabindex="-1">1. 호수(유닛) 일괄 등록 <a class="header-anchor" href="#_1-호수-유닛-일괄-등록" aria-label="Permalink to &quot;1. 호수(유닛) 일괄 등록&quot;">​</a></h3><p>수십~수백 세대에 달하는 유닛을 라인별로 한 번에 고속 생성하는 기능입니다.</p><table tabindex="0"><thead><tr><th style="text-align:left;">라벨</th><th style="text-align:center;">필수입력</th><th style="text-align:left;">상세 설명 및 실무 기준</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>동(건물) 선택</strong></td><td style="text-align:center;"><strong>필수</strong></td><td style="text-align:left;">유닛을 생성할 대상 동 선택</td></tr><tr><td style="text-align:left;"><strong>등록라인</strong></td><td style="text-align:center;"><strong>필수</strong></td><td style="text-align:left;">유닛을 생성할 라인 번호 (숫자 입력, 예: <code>1</code>, <code>2</code>)</td></tr><tr><td style="text-align:left;"><strong>타입선택</strong></td><td style="text-align:center;"><strong>필수</strong></td><td style="text-align:left;">해당 라인/층에 적용할 유닛 타입(평형) 선택</td></tr><tr><td style="text-align:left;"><strong>시작층</strong></td><td style="text-align:center;"><strong>필수</strong></td><td style="text-align:left;">생성을 시작할 층 번호 (지하층은 -1 등 음수 입력)</td></tr><tr><td style="text-align:left;"><strong>종료층</strong></td><td style="text-align:center;"><strong>필수</strong></td><td style="text-align:left;">생성을 종료할 층 범위 (시작층만 입력 시 1개 층만 생성)</td></tr></tbody></table><blockquote><p><strong>💡 자동 명칭 생성 규칙</strong>: 호수 명칭은 <code>층번호 + 2자리 라인번호</code> 조합으로 자동 생성됩니다.</p><ul><li>예: 10층 1호 라인 → <code>1001호</code>, 3층 2호 라인 → <code>302호</code></li></ul></blockquote><h3 id="_2-유닛-개별-관리-및-홀딩-holding" tabindex="-1">2. 유닛 개별 관리 및 홀딩 (Holding) <a class="header-anchor" href="#_2-유닛-개별-관리-및-홀딩-holding" aria-label="Permalink to &quot;2. 유닛 개별 관리 및 홀딩 (Holding)&quot;">​</a></h3><p>생성된 유닛의 세부 정보를 수정하거나, 특정 사유로 분양을 제한(홀딩)할 때 사용합니다.</p><table tabindex="0"><thead><tr><th style="text-align:left;">라벨</th><th style="text-align:center;">필수입력</th><th style="text-align:left;">상세 설명 및 실무 기준</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>타입</strong></td><td style="text-align:center;"><strong>필수</strong></td><td style="text-align:left;">해당 유닛의 평형 타입 수정</td></tr><tr><td style="text-align:left;"><strong>층범위타입</strong></td><td style="text-align:center;"><strong>필수</strong></td><td style="text-align:left;">분양가 산정 기준이 되는 층 범위 조건 연결 (저층/기준층/로열층 등)</td></tr><tr><td style="text-align:left;"><strong>호수/라인/층수</strong></td><td style="text-align:center;"><strong>필수</strong></td><td style="text-align:left;">자동 생성된 유닛 명칭 및 물리적 위치 정보 수정</td></tr><tr><td style="text-align:left;"><strong>홀딩여부</strong></td><td style="text-align:center;"></td><td style="text-align:left;">체크 시 해당 유닛을 <strong>&#39;분양 제한(계약 불가)&#39;</strong> 상태로 잠금 설정</td></tr><tr><td style="text-align:left;"><strong>홀딩사유</strong></td><td style="text-align:center;"></td><td style="text-align:left;">홀딩 설정 사유를 명시 (예: <code>회사보유분</code>, <code>대토 지주 우선배정</code>, <code>분양 보류</code>)</td></tr></tbody></table><h2 id="_3-신입사원을-위한-실무-가이드" tabindex="-1">3. 신입사원을 위한 실무 가이드 <a class="header-anchor" href="#_3-신입사원을-위한-실무-가이드" aria-label="Permalink to &quot;3. 신입사원을 위한 실무 가이드&quot;">​</a></h2><ul><li><strong>💡 시각적 유닛 배치도 활용</strong>: <ul><li>화면 왼쪽의 동호수 배치도(조감 그리드)를 통해 등록된 유닛 현황을 시각적으로 확인할 수 있습니다. <a href="/project/types.html">타입 정보 등록</a>에서 지정한 색상에 따라 평형별 배치가 색상 블록으로 직관적으로 표출됩니다.</li></ul></li><li><strong>💡 홀딩(Holding)의 실무적 의의</strong>: <ul><li>모델하우스 오픈 전 조합원 배정분이나 회사 보유분 세대는 분양 상담사가 임의로 계약을 체결하지 못하도록 반드시 **&#39;홀딩여부&#39;**를 체크해 두어야 합니다. 홀딩된 세대는 계약 등록 시 선택 목록에서 자동으로 제외되거나 경고창이 표시됩니다.</li></ul></li></ul>',21)])])}const u=e(a,[["render",d]]);export{y as __pageData,u as default};
